import sys

MOD = 998244353

def extended_gcd(a, b):
    if a == 0:
        return (b, 0, 1)
    else:
        g, y, x = extended_gcd(b % a, a)
        return (g, x - (b // a) * y, y)

def inverse(a, mod):
    g, x, y = extended_gcd(a, mod)
    if g != 1:
        return 0
    else:
        return (x % mod)

def mod_fraction(a, b, mod):
    inv_b = inverse(b, mod)
    if inv_b == 0:
        return -1
    return (inv_b * a) % mod

def solve(N, M, K):
    invM = inverse(M, MOD)
    expect = [0] * (K + 1)
    expect[0] = 1
    poly = [0] * (K + 1)
    poly[0] = 1
    currentExpect = 1
    for k in range(1, K + 1):
        numerator = 1
        for i in range(k):
            numerator *= (N - i)
            numerator %= MOD
        currentExpect = (numerator * invM) % MOD
        for i in range(k, -1, -1):
            prev = poly[i - 1] if i > 0 else 0
            poly[i] = prev - (k - 1) * poly[i]
            poly[i] = poly[i] % MOD
        expect[k] = currentExpect
        for i in range(k - 1, -1, -1):
            expect[k] -= poly[i] * expect[i]
            expect[k] = expect[k] % MOD
    print(expect[K])

def main():
    input_line = sys.stdin.read().strip()
    N, M, K = map(int, input_line.split())
    solve(N, M, K)

